window.PTD_BANK=[{"id": "md-001", "category": "Signs", "question": "A red octagonal sign appears at an empty intersection. What must you do?", "answer": "Come to a complete stop and yield before proceeding", "choices": ["Come to a complete stop and yield before proceeding", "Slow down only if traffic is approaching", "Stop only if another car is visible", "Yield without stopping"], "explanation": "A STOP sign requires a complete stop at the stop line, before the crosswalk if no line exists, or before entering the intersection. Yield to traffic and pedestrians before proceeding.", "manual_ref": "Sec. 4.B Traffic Signs", "concept_group": "md-001", "img": "img/md-001.webp"}, {"id": "md-002", "category": "Signs", "question": "You see an upside-down red-and-white triangle. What does it require?", "answer": "Yield the right-of-way, stopping if necessary", "choices": ["Yield the right-of-way, stopping if necessary", "Stop for exactly three seconds", "Speed up to merge ahead", "Proceed because you have priority"], "explanation": "A YIELD sign requires slowing and giving way; stop if necessary.", "manual_ref": "Sec. 4.B Traffic Signs", "concept_group": "md-002", "img": "img/md-002.webp"}, {"id": "md-003", "category": "Signs", "question": "A round yellow warning sign with a black X and RR means what?", "answer": "A railroad crossing is ahead", "choices": ["A railroad crossing is ahead", "A school crossing is ahead", "A roundabout begins", "Trains must yield to cars"], "explanation": "The circular RR advance warning sign alerts you to railroad tracks ahead.", "manual_ref": "Sec. 4.B Traffic Signs", "concept_group": "md-003", "img": "img/md-003.webp"}, {"id": "md-004", "category": "Signs", "question": "What does a yellow diamond-shaped sign generally indicate?", "answer": "A warning about a potential road hazard", "choices": ["A warning about a potential road hazard", "A mandatory speed limit", "A hospital entrance", "A permitted parking zone"], "explanation": "Yellow diamond signs generally warn of conditions ahead.", "manual_ref": "Sec. 4.B Traffic Signs", "concept_group": "md-004", "img": "img/md-004.webp"}, {"id": "md-005", "category": "Signs", "question": "A five-sided fluorescent yellow-green sign typically alerts you to what?", "answer": "A school zone or school crossing", "choices": ["A school zone or school crossing", "A railroad crossing", "An interstate exit", "A one-way street"], "explanation": "Pentagon-shaped signs identify school areas and crossings.", "manual_ref": "Sec. 4.B Traffic Signs", "concept_group": "md-005", "img": "img/md-005.webp"}, {"id": "md-006", "category": "Signs", "question": "What does an orange diamond-shaped sign typically warn about?", "answer": "Roadwork or temporary traffic conditions", "choices": ["Roadwork or temporary traffic conditions", "A recreational area", "A hospital nearby", "A permanent speed limit change"], "explanation": "Orange signs indicate construction and temporary work-zone hazards.", "manual_ref": "Sec. 4.B Traffic Signs", "concept_group": "md-006", "img": "img/md-006.webp"}, {"id": "md-007", "category": "Signs", "question": "A white rectangular sign reading SPEED LIMIT 35 tells you what?", "answer": "The maximum lawful speed under ideal conditions", "choices": ["The maximum lawful speed under ideal conditions", "A recommended minimum speed", "A speed you must maintain in fog", "A limit that applies only during daylight"], "explanation": "Posted limits are maximums, not a guarantee that a speed is safe.", "manual_ref": "Sec. 4.B Traffic Signs", "concept_group": "md-007", "img": "img/md-007.webp"}, {"id": "md-008", "category": "Signs", "question": "A red circle with a diagonal slash over a U-turn arrow means what?", "answer": "U-turns are prohibited", "choices": ["U-turns are prohibited", "U-turns are required", "Only buses may U-turn", "U-turns are allowed after stopping"], "explanation": "The slash means the pictured maneuver is prohibited.", "manual_ref": "Sec. 3.H U-turn", "concept_group": "md-008", "img": "img/md-008.webp"}, {"id": "md-009", "category": "Signals", "question": "Your signal turns green, but a pedestrian is still crossing in front of you. What should you do?", "answer": "Wait and yield until the pedestrian is safely clear", "choices": ["Wait and yield until the pedestrian is safely clear", "Proceed because green always gives you priority", "Sound the horn and move slowly", "Drive around the pedestrian in the crosswalk"], "explanation": "Green does not cancel the duty to yield to people lawfully in the crosswalk.", "manual_ref": "Sec. 4.A Traffic Signals", "concept_group": "md-009", "img": "img/md-009.webp"}, {"id": "md-010", "category": "Signals", "question": "A steady yellow traffic signal appears as you approach. What is the safest response?", "answer": "Stop if you can do so safely before entering the intersection", "choices": ["Stop if you can do so safely before entering the intersection", "Accelerate to beat the red light", "Stop abruptly regardless of following traffic", "Treat it like a flashing yellow signal"], "explanation": "Steady yellow warns that the light is changing to red; stop when safe.", "manual_ref": "Sec. 4.A Traffic Signals", "concept_group": "md-010", "img": "img/md-010.webp"}, {"id": "md-011", "category": "Signals", "question": "A flashing red traffic signal should be treated like what?", "answer": "A stop sign", "choices": ["A stop sign", "A green signal", "A flashing yellow signal", "A yield sign without a required stop"], "explanation": "Flashing red means stop completely, then proceed when safe.", "manual_ref": "Sec. 4.A Traffic Signals", "concept_group": "md-011", "img": "img/md-011.webp"}, {"id": "md-012", "category": "Signals", "question": "At a flashing yellow traffic signal, you should do what?", "answer": "Slow down and proceed with caution", "choices": ["Slow down and proceed with caution", "Come to a complete stop every time", "Accelerate because cross traffic must stop", "Turn only; going straight is forbidden"], "explanation": "Flashing yellow calls for caution, not an automatic full stop.", "manual_ref": "Sec. 4.A Traffic Signals", "concept_group": "md-012", "img": "img/md-012.webp"}, {"id": "md-013", "category": "Signals", "question": "A red arrow points left at your intersection. What does it mean?", "answer": "Do not make the left turn while the red arrow is displayed", "choices": ["Do not make the left turn while the red arrow is displayed", "Turn left after a rolling stop", "Turn left if there are no pedestrians", "Turn left if the opposing light is green"], "explanation": "A red arrow prohibits movement in the direction of the arrow.", "manual_ref": "Sec. 4.A Traffic Signals", "concept_group": "md-013", "img": "img/md-013.webp"}, {"id": "md-014", "category": "Signals", "question": "A green arrow lights for your turn. Which statement remains true?", "answer": "Yield to any pedestrians or vehicles lawfully in the intersection", "choices": ["Yield to any pedestrians or vehicles lawfully in the intersection", "You may ignore pedestrians in the crosswalk", "You must stop before following the arrow", "You may enter a blocked intersection"], "explanation": "A green arrow authorizes the indicated movement, but you must still avoid conflicts.", "manual_ref": "Sec. 4.A Traffic Signals", "concept_group": "md-014", "img": "img/md-014.webp"}, {"id": "md-015", "category": "Signals", "question": "Traffic lights are dark because of a power failure. What should drivers do?", "answer": "Treat the intersection as an all-way stop", "choices": ["Treat the intersection as an all-way stop", "Assume the busiest road has priority", "Proceed at the posted speed", "Follow the last color that was illuminated"], "explanation": "At an inoperative traffic signal, stop at the stop line, or before the crosswalk/intersection if none exists. Yield to traffic and pedestrians already in the intersection and proceed only when safe.", "manual_ref": "Sec. 4 (signal not working)", "concept_group": "dark-signal", "img": "img/md-015.webp"}, {"id": "md-016", "category": "Signals", "question": "A police officer directs you to stop even though your light is green. What should you do?", "answer": "Obey the officer and stop", "choices": ["Obey the officer and stop", "Follow the green signal instead", "Proceed if your lane is clear", "Stop only if the officer uses a whistle"], "explanation": "An officer directing traffic takes precedence over traffic control signals.", "manual_ref": "Sec. 4.A Traffic Signals", "concept_group": "md-016", "img": "img/md-016.webp"}, {"id": "md-017", "category": "Right-of-way", "question": "At an uncontrolled intersection, two vehicles arrive at the same time. One is on your right. Who should go first?", "answer": "The vehicle on your right", "choices": ["The vehicle on your right", "The vehicle traveling faster", "The larger vehicle", "The vehicle on your left"], "explanation": "At an otherwise equal uncontrolled intersection, yield to the vehicle on your right.", "manual_ref": "Sec. 3.B Right-of-Way", "concept_group": "md-017", "img": "img/md-017.webp"}, {"id": "md-018", "category": "Right-of-way", "question": "At a four-way stop, another driver stops before you. Who normally goes first?", "answer": "The driver who stopped first", "choices": ["The driver who stopped first", "Whoever flashes headlights first", "The driver turning left", "Whoever is driving straight fastest"], "explanation": "At all-way stops, first to stop is generally first to proceed, once safe.", "manual_ref": "Sec. 3.B Right-of-Way", "concept_group": "four-way-stop", "img": "img/md-018.webp"}, {"id": "md-019", "category": "Right-of-way", "question": "You are turning left on a solid green light. An oncoming car is going straight. What should you do?", "answer": "Yield to the oncoming car", "choices": ["Yield to the oncoming car", "Turn first because you have green", "Wait only if the oncoming car signals", "Honk and complete the turn"], "explanation": "A permissive left turn yields to oncoming traffic and pedestrians.", "manual_ref": "Sec. 3.B Right-of-Way", "concept_group": "md-019", "img": "img/md-019.webp"}, {"id": "md-020", "category": "Right-of-way", "question": "You are entering a road from a private driveway. Who has the right-of-way?", "answer": "Traffic and pedestrians already using the road or sidewalk", "choices": ["Traffic and pedestrians already using the road or sidewalk", "Your vehicle because you are entering", "Only vehicles approaching from your left", "Only vehicles traveling above the speed limit"], "explanation": "Drivers entering from a driveway must yield to roadway users and pedestrians.", "manual_ref": "Sec. 3.B Right-of-Way", "concept_group": "md-020", "img": "img/md-020.webp"}, {"id": "md-021", "category": "Right-of-way", "question": "An emergency vehicle approaches from behind with lights and siren. What should you generally do?", "answer": "Safely move toward the right edge and stop", "choices": ["Safely move toward the right edge and stop", "Speed up to clear its route", "Stop immediately in the center of your lane", "Turn left at the next intersection"], "explanation": "Yield promptly and safely to emergency responders; do not block intersections.", "manual_ref": "Sec. 7.B Emergency Vehicles", "concept_group": "md-021", "img": "img/md-021.webp"}, {"id": "md-022", "category": "Right-of-way", "question": "A pedestrian enters a marked crosswalk as you approach. What should you do?", "answer": "Yield and stop as needed for the pedestrian", "choices": ["Yield and stop as needed for the pedestrian", "Continue if you are under the speed limit", "Honk because pedestrians must wait", "Drive behind them without slowing"], "explanation": "Drivers must yield to pedestrians in crosswalks as required by law.", "manual_ref": "Sec. 7.A Pedestrian Right-of-Way", "concept_group": "crosswalk", "img": "img/md-022.webp"}, {"id": "md-023", "category": "Road markings", "question": "A broken white line between two lanes means what?", "answer": "You may change lanes when safe", "choices": ["You may change lanes when safe", "Passing is prohibited in both directions", "Traffic moves in opposite directions", "You must stop before crossing it"], "explanation": "Broken white lines separate same-direction lanes where changing lanes is generally permitted.", "manual_ref": "Sec. 4.C Pavement Markings", "concept_group": "md-023", "img": "img/md-023.webp"}, {"id": "md-024", "category": "Road markings", "question": "A solid white line between travel lanes means what?", "answer": "Lane changes are discouraged; cross only when permitted and safe", "choices": ["Lane changes are discouraged; cross only when permitted and safe", "The lanes carry opposite-direction traffic", "You must make a U-turn", "You may change lanes without checking mirrors"], "explanation": "A single solid white line separates same-direction lanes where lane changing is discouraged. Double solid white lines prohibit lane changes.", "manual_ref": "Sec. 4.C Pavement Markings", "concept_group": "md-024", "img": "img/md-024.webp"}, {"id": "md-025", "category": "Road markings", "question": "A broken yellow centerline is on your side of a two-way road. What does it mean?", "answer": "Passing may be allowed when legal and safe", "choices": ["Passing may be allowed when legal and safe", "Passing is always prohibited", "All traffic goes the same direction", "The road is about to end"], "explanation": "A broken yellow line on your side permits passing if visibility and conditions allow.", "manual_ref": "Sec. 3.I Passing", "concept_group": "md-025", "img": "img/md-025.webp"}, {"id": "md-026", "category": "Road markings", "question": "Two solid yellow centerlines separate opposing traffic. What is generally prohibited?", "answer": "Crossing them to pass another vehicle", "choices": ["Crossing them to pass another vehicle", "Turning into a driveway where legally allowed", "Driving alongside the centerline", "Stopping at an intersection"], "explanation": "Double solid yellow lines generally prohibit passing across the center.", "manual_ref": "Sec. 3.I Passing", "concept_group": "md-026", "img": "img/md-026.webp"}, {"id": "md-027", "category": "Road markings", "question": "A white stop line is painted before a crosswalk. Where should you stop?", "answer": "Before the stop line", "choices": ["Before the stop line", "Inside the crosswalk", "Beyond the intersection", "With your front tires on the line"], "explanation": "Stop before the stop line to keep the crosswalk clear.", "manual_ref": "Sec. 4.C Pavement Markings", "concept_group": "md-027", "img": "img/md-027.webp"}, {"id": "md-028", "category": "Road markings", "question": "You approach a lane marked with a white left-turn-only arrow. What should you do?", "answer": "Turn left from that lane", "choices": ["Turn left from that lane", "Go straight if there is no traffic", "Turn right after signaling", "Stop and wait for another lane"], "explanation": "Lane-use arrows tell you the movements allowed from that lane.", "manual_ref": "Sec. 4.C Pavement Markings", "concept_group": "md-028", "img": "img/md-028.webp"}, {"id": "md-029", "category": "Speed", "question": "The speed limit is 55 mph, but dense fog limits your visibility. What speed is appropriate?", "answer": "A slower speed that allows you to stop within visible distance", "choices": ["A slower speed that allows you to stop within visible distance", "Exactly 55 mph because that is posted", "60 mph to leave the fog quickly", "The speed of the car behind you"], "explanation": "Always adapt speed to visibility, traction and road conditions.", "manual_ref": "Sec. 5.C Driving in Fog", "concept_group": "fog", "img": "img/md-029.webp"}, {"id": "md-030", "category": "Speed", "question": "A driver behind you is tailgating. What is the best response?", "answer": "Increase space ahead and allow them to pass when safe", "choices": ["Increase space ahead and allow them to pass when safe", "Brake suddenly to warn them", "Speed well above the limit", "Maintain eye contact through the mirror"], "explanation": "More space ahead gives you room to brake gradually; do not retaliate.", "manual_ref": "Sec. 3.C Understanding Vehicle Speed", "concept_group": "tailgater", "img": "img/md-030.webp"}, {"id": "md-031", "category": "Speed", "question": "Why should you reduce speed before entering a sharp curve?", "answer": "Traction and steering control are reduced at higher speeds", "choices": ["Traction and steering control are reduced at higher speeds", "Speed limits do not apply in curves", "Braking mid-curve is always safer", "A curve sign means you must stop"], "explanation": "Slow before the curve to reduce the risk of losing traction.", "manual_ref": "Sec. 3.C Understanding Vehicle Speed", "concept_group": "curve-speed", "img": "img/md-031.webp"}, {"id": "md-032", "category": "Speed", "question": "A school crossing is busy with children. Which action is safest?", "answer": "Slow down, scan carefully and be prepared to stop", "choices": ["Slow down, scan carefully and be prepared to stop", "Maintain the posted speed regardless of activity", "Honk continuously so children move", "Follow the car ahead without scanning"], "explanation": "Children can move unpredictably; use extra caution near schools.", "manual_ref": "Sec. 3.C Understanding Vehicle Speed", "concept_group": "md-032", "img": "img/md-032.webp"}, {"id": "md-033", "category": "Space", "question": "Under ideal conditions, what following distance does the Maryland manual recommend, and when should it increase?", "answer": "3 to 4 seconds, and more on wet, snowy or icy roads", "choices": ["3 to 4 seconds, and more on wet, snowy or icy roads", "1 second, in all conditions", "2 car lengths, regardless of weather", "3 to 4 seconds, but less at night"], "explanation": "Keep at least 3 to 4 seconds behind the vehicle ahead in ideal conditions. Increase the gap on wet roads, and even more on snow or ice.", "manual_ref": "Sec. 3.D Following Distance", "concept_group": "md-033", "img": "img/md-033.webp"}, {"id": "md-034", "category": "Space", "question": "Why is following a large truck closely especially risky?", "answer": "The truck can block your view of hazards ahead", "choices": ["The truck can block your view of hazards ahead", "Trucks never brake suddenly", "Your headlights become brighter", "Trucks must always yield to cars behind them"], "explanation": "Large vehicles create sight-line blind spots and need extra stopping room.", "manual_ref": "Sec. 7.C Large Trucks and Buses", "concept_group": "md-034", "img": "img/md-034.webp"}, {"id": "md-035", "category": "Space", "question": "You cannot see a truck driver in the truck’s side mirror. What should you assume?", "answer": "The driver may not be able to see you", "choices": ["The driver may not be able to see you", "The driver sees your whole vehicle", "You have priority to pass", "The truck is preparing to stop"], "explanation": "Avoid lingering in large-vehicle blind spots.", "manual_ref": "Sec. 7.C Large Trucks and Buses", "concept_group": "truck-mirror", "img": "img/md-035.webp"}, {"id": "md-036", "category": "Space", "question": "When should you check blind spots before changing lanes?", "answer": "Before moving, after checking mirrors and signaling", "choices": ["Before moving, after checking mirrors and signaling", "Only after the lane change begins", "Only on multilane highways", "Only when you hear a horn"], "explanation": "Mirrors do not reveal every vehicle; check over your shoulder.", "manual_ref": "Sec. 3.D Following Distance", "concept_group": "blind-spot", "img": "img/md-036.webp"}, {"id": "md-037", "category": "Space", "question": "What is the safest way to merge onto a highway?", "answer": "Adjust speed to traffic, find a safe gap and yield as needed", "choices": ["Adjust speed to traffic, find a safe gap and yield as needed", "Stop at the end of every acceleration lane", "Merge immediately without checking", "Assume highway drivers must brake for you"], "explanation": "Use the acceleration lane to match speed and merge safely.", "manual_ref": "Sec. 5.J Interstate Driving", "concept_group": "highway-merge", "img": "img/md-037.webp"}, {"id": "md-038", "category": "Weather", "question": "Heavy rain starts and your tires lose grip on standing water. What should you do?", "answer": "Take your foot off the gas, do not brake, and keep the car going straight", "choices": ["Take your foot off the gas, do not brake, and keep the car going straight", "Brake sharply and turn quickly", "Accelerate to regain traction", "Steer hard toward the shoulder"], "explanation": "If you hydroplane, take your foot off the gas, do not apply the brakes, keep going straight, and slow down until you regain control.", "manual_ref": "Sec. 5.F Hydroplaning", "concept_group": "md-038", "img": "img/md-038.webp"}, {"id": "md-039", "category": "Weather", "question": "When driving in fog, which headlights are generally best?", "answer": "Low beams", "choices": ["Low beams", "High beams", "Parking lights only", "No lights if it is daytime"], "explanation": "High beams can reflect from fog and reduce visibility.", "manual_ref": "Sec. 5.C Driving in Fog", "concept_group": "fog", "img": "img/md-039.webp"}, {"id": "md-040", "category": "Weather", "question": "You approach an icy bridge. What is the safest approach?", "answer": "Slow before the bridge and avoid abrupt control inputs", "choices": ["Slow before the bridge and avoid abrupt control inputs", "Accelerate to cross quickly", "Brake hard on the bridge", "Use cruise control to maintain speed"], "explanation": "Bridges may freeze before adjacent pavement; smooth inputs preserve traction.", "manual_ref": "Sec. 5.D Inclement Weather", "concept_group": "md-040", "img": "img/md-040.webp"}, {"id": "md-042", "category": "Weather", "question": "At night, oncoming headlights are dazzling you. Where should you look?", "answer": "Toward the right edge of your lane while maintaining control", "choices": ["Toward the right edge of your lane while maintaining control", "Directly into the headlights", "Down at the dashboard", "At the rearview mirror only"], "explanation": "Looking toward the right edge helps avoid glare without losing road position.", "manual_ref": "Sec. 5.B Driving at Night", "concept_group": "md-042", "img": "img/md-042.webp"}, {"id": "md-043", "category": "Weather", "question": "When should high-beam headlights be dimmed?", "answer": "At least 500 feet before an oncoming vehicle, or when following within 300 feet", "choices": ["At least 500 feet before an oncoming vehicle, or when following within 300 feet", "Only when entering a city", "Only when it rains", "When an oncoming vehicle is 50 feet away"], "explanation": "Switch to low beams at least 500 feet before reaching oncoming vehicles, and when following a vehicle 300 feet or less ahead.", "manual_ref": "Sec. 5.A Low/High Beams", "concept_group": "md-043", "img": "img/md-043.webp"}, {"id": "md-044", "category": "Impairment", "question": "Which statement about alcohol and driving is most accurate?", "answer": "Even small amounts can impair judgment and reaction time", "choices": ["Even small amounts can impair judgment and reaction time", "Coffee immediately reverses alcohol impairment", "Only beer affects driving ability", "Experience prevents alcohol-related impairment"], "explanation": "Alcohol affects perception, decisions and motor coordination.", "manual_ref": "Sec. 6.A Alcohol, Drugs and Driving", "concept_group": "bac", "img": "img/md-044.webp"}, {"id": "md-045", "category": "Impairment", "question": "A prescription medicine says it may cause drowsiness. What should you do before driving?", "answer": "Understand its effects and avoid driving if impaired", "choices": ["Understand its effects and avoid driving if impaired", "Drive only on roads you know", "Drink an energy drink and assume you are safe", "Drive faster to shorten the trip"], "explanation": "Legal medications can impair driving; follow medical guidance and warning labels.", "manual_ref": "Sec. 6.A Alcohol, Drugs and Driving", "concept_group": "medication", "img": "img/md-045.webp"}, {"id": "md-046", "category": "Impairment", "question": "You are struggling to keep your eyes open while driving. What is the safest response?", "answer": "Pull over somewhere safe and rest or switch drivers", "choices": ["Pull over somewhere safe and rest or switch drivers", "Open the window and keep driving", "Turn up the music and accelerate", "Follow the taillights ahead"], "explanation": "Drowsiness seriously impairs attention and reaction; stop driving safely.", "manual_ref": "Sec. 6.D Drowsy Driving", "concept_group": "drowsy", "img": "img/md-046.webp"}, {"id": "md-047", "category": "Impairment", "question": "A friend says they feel fine after several drinks and offers to drive. What should you do?", "answer": "Arrange a sober driver or another safe ride", "choices": ["Arrange a sober driver or another safe ride", "Let them drive if they speak clearly", "Ask them to drink coffee first", "Let them drive only on local roads"], "explanation": "Feeling fine does not establish sobriety or fitness to drive.", "manual_ref": "Sec. 6.A Alcohol, Drugs and Driving", "concept_group": "impaired-friend", "img": "img/md-047.webp"}, {"id": "md-048", "category": "Sharing", "question": "You pass a bicyclist on a narrow roadway. What should you do?", "answer": "Leave at least 3 feet, and wait if oncoming traffic prevents it", "choices": ["Leave at least 3 feet, and wait if oncoming traffic prevents it", "Pass closely to avoid crossing the centerline", "Honk continuously and squeeze by", "Assume the bicyclist must leave the roadway"], "explanation": "Pass a bicyclist like any slow-moving vehicle: wait until oncoming traffic is clear, then leave at least 3 feet between your vehicle and the bicycle.", "manual_ref": "Sec. 7.F Bicycles", "concept_group": "bike-pass", "img": "img/md-048.webp"}, {"id": "md-049", "category": "Sharing", "question": "A motorcycle is ahead in your lane. What following space should you allow?", "answer": "A generous following gap, especially on slippery roads", "choices": ["A generous following gap, especially on slippery roads", "Less space because motorcycles are shorter", "Exactly half a car length", "No gap when traffic is slow"], "explanation": "Motorcycles can stop quickly and are harder to see; leave extra room.", "manual_ref": "Sec. 7.E Motorcycles", "concept_group": "md-049", "img": "img/md-049.webp"}, {"id": "md-050", "category": "Sharing", "question": "A school bus is stopped with red lights flashing on an undivided two-way road. What must you do?", "answer": "Stop at least 20 feet away and stay stopped until the bus moves or turns off its red lights", "choices": ["Stop at least 20 feet away and stay stopped until the bus moves or turns off its red lights", "Pass slowly if no children are visible", "Stop only if you are directly behind the bus", "Keep going if you are traveling in the opposite direction"], "explanation": "Stop at least 20 feet from the back or front of a school bus with flashing red lights. Do not move until the bus starts moving or turns off its red lights.", "manual_ref": "Sec. 7.D School Buses", "concept_group": "school-bus-stop", "img": "img/md-050.webp"}, {"id": "md-051", "category": "Sharing", "question": "A school bus has amber warning lights flashing but is still moving. What should you expect?", "answer": "The bus may soon stop; slow and prepare to stop", "choices": ["The bus may soon stop; slow and prepare to stop", "The bus is signaling a lane change only", "You may pass at any speed", "The bus has broken down"], "explanation": "Amber bus lights warn that a stop is approaching.", "manual_ref": "Sec. 7.D School Buses", "concept_group": "md-051", "img": "img/md-051.webp"}, {"id": "md-052", "category": "Sharing", "question": "You see a pedestrian with a white cane near a crossing. What is the safest action?", "answer": "Exercise special caution and yield as required", "choices": ["Exercise special caution and yield as required", "Sound your horn and continue", "Assume they can see your turn signal", "Pass closely to reduce delay"], "explanation": "A white cane may identify a blind pedestrian; yield and avoid startling them.", "manual_ref": "Sec. 7.A Pedestrian Right-of-Way", "concept_group": "md-052", "img": "img/md-052.webp"}, {"id": "md-055", "category": "Parking", "question": "You are about to open your car door beside a bike lane. What should you do first?", "answer": "Check for cyclists and other approaching traffic", "choices": ["Check for cyclists and other approaching traffic", "Open quickly so cyclists can react", "Rely only on your passenger to look", "Open the door halfway to warn others"], "explanation": "Dooring a cyclist can cause a serious crash; check before opening.", "manual_ref": "Sec. 3.J General Parking Rules", "concept_group": "md-055", "img": "img/md-055.webp"}, {"id": "md-058", "category": "Emergencies", "question": "Your vehicle begins to skid on a slippery curve. What is the best general response?", "answer": "Release the gas or brake, steer in the direction of the skid, and look where you want to go", "choices": ["Release the gas or brake, steer in the direction of the skid, and look where you want to go", "Brake hard and jerk the wheel", "Accelerate sharply", "Turn away from the intended path"], "explanation": "To recover from a skid: release the pedal you are using, steer in the direction you are skidding, look where you want to go, and brake only after the tires grip again.", "manual_ref": "Sec. 5.E Skidding", "concept_group": "md-058", "img": "img/md-058.webp"}, {"id": "md-059", "category": "Emergencies", "question": "You are involved in a crash with possible injuries. What should you do?", "answer": "Stay at the scene, call 911, and do not move the vehicles", "choices": ["Stay at the scene, call 911, and do not move the vehicles", "Leave if your vehicle still runs", "Move the vehicles out of the road first", "Wait for someone else to call for help"], "explanation": "After a crash where someone is injured, turn on your flashers, stay at the scene, call 911, report the number of people and injuries and the location, and do not move the vehicles.", "manual_ref": "Sec. 8.A Crashes", "concept_group": "md-059", "img": "img/md-059.webp"}, {"id": "md-060", "category": "Maryland", "question": "What does the standard Maryland Class C knowledge test require to pass?", "answer": "At least 22 correct answers out of 25", "choices": ["At least 22 correct answers out of 25", "At least 20 correct answers out of 25", "At least 18 correct answers out of 25", "Every question correct"], "explanation": "The Maryland MVA sets a passing score of 88%, or 22 of 25 questions.", "manual_ref": "Sec. 1.B Knowledge Test", "concept_group": "md-060", "img": "img/md-060.webp"}, {"id": "md-061", "category": "Maryland", "question": "How long is the standard Maryland Class C knowledge test?", "answer": "20 minutes", "choices": ["20 minutes", "10 minutes", "30 minutes", "45 minutes"], "explanation": "The official knowledge test has a 20-minute time limit.", "manual_ref": "Sec. 1.B Knowledge Test", "concept_group": "md-061", "img": "img/md-061.webp"}, {"id": "md-062", "category": "Maryland", "question": "Which subjects are covered by the Maryland knowledge test?", "answer": "Traffic laws, road signs and safe driving", "choices": ["Traffic laws, road signs and safe driving", "Only vehicle maintenance", "Only parking maneuvers", "Only highway speed limits"], "explanation": "The Maryland MVA tests rules of the road, signs and safe driving.", "manual_ref": "Sec. 1.B Knowledge Test", "concept_group": "md-062", "img": "img/md-062.webp"}, {"id": "md-063", "category": "Maryland", "question": "You are a learner permit holder. Which action best reflects safe supervised practice?", "answer": "Drive with an eligible supervising driver and obey permit restrictions", "choices": ["Drive with an eligible supervising driver and obey permit restrictions", "Drive alone if the trip is short", "Let an unlicensed friend supervise", "Ignore permit restrictions on quiet roads"], "explanation": "Permit privileges are conditional and require appropriate supervision.", "manual_ref": "Sec. 2.A and 10.B", "concept_group": "md-063", "img": "img/md-063.webp"}, {"id": "md-064", "category": "Maryland", "question": "Which statement about texting while driving is safest and consistent with Maryland restrictions?", "answer": "Do not text while operating the vehicle", "choices": ["Do not text while operating the vehicle", "Text if stopped at a red light", "Text only while traveling below 20 mph", "Text if using both hands briefly"], "explanation": "Texting distracts from driving and is prohibited under Maryland law.", "manual_ref": "Sec. 6.C Distracted Driving", "concept_group": "phone", "img": "img/md-064.webp"}, {"id": "md-065", "category": "Maryland", "question": "A learner driver wants to use a hands-free phone for casual conversation. What should they do?", "answer": "Do not use it; permit holders may not use any wireless device, even hands-free, except to call 911", "choices": ["Do not use it; permit holders may not use any wireless device, even hands-free, except to call 911", "Use it whenever traffic is light", "Use it if both hands remain on the wheel", "Use it only while turning"], "explanation": "Learner's Permit and Provisional License holders may not use any wireless communication device, including a hands-free phone, while driving. The only exception is a 911 emergency call.", "manual_ref": "Sec. 9.A Restrictions", "concept_group": "phone-learner", "img": "img/md-065.webp"}, {"id": "md-066", "category": "Turns", "question": "Before turning, you should signal when?", "answer": "Far enough in advance to warn others and check that the turn is safe", "choices": ["Far enough in advance to warn others and check that the turn is safe", "Only after beginning the turn", "Only if another car is behind you", "Only when the light is red"], "explanation": "Early signaling communicates intent but never grants right-of-way.", "manual_ref": "Sec. 3.G Turning", "concept_group": "md-066", "img": "img/md-066.webp"}, {"id": "md-067", "category": "Turns", "question": "You miss your highway exit. What should you do?", "answer": "Continue past it and look for a safe way to re-enter; never back up on the highway", "choices": ["Continue past it and look for a safe way to re-enter; never back up on the highway", "Back up along the shoulder", "Make a U-turn through the median", "Stop in the travel lane"], "explanation": "If you exit at the wrong place or miss an exit, keep going, then look for a way back. Never stop and back up on any part of the highway.", "manual_ref": "Sec. 5.J Interstate Driving", "concept_group": "missed-exit", "img": "img/md-067.webp"}, {"id": "md-068", "category": "Turns", "question": "A right turn on red is allowed at an intersection with no prohibiting sign. What must you do first?", "answer": "Stop completely and yield to pedestrians and traffic", "choices": ["Stop completely and yield to pedestrians and traffic", "Slow without stopping if no cars appear", "Honk to alert pedestrians", "Turn before the crosswalk"], "explanation": "A permitted right turn on red requires a complete stop and yielding.", "manual_ref": "Sec. 3.G Turning", "concept_group": "md-068", "img": "img/md-068.webp"}, {"id": "md-069", "category": "Turns", "question": "You plan to turn right and a cyclist is traveling beside you. What should you do?", "answer": "Check the bike lane and yield appropriately before turning", "choices": ["Check the bike lane and yield appropriately before turning", "Turn across the cyclist’s path", "Assume the cyclist must stop", "Honk and turn immediately"], "explanation": "Watch for cyclists when crossing their path, especially during right turns.", "manual_ref": "Sec. 7.F Bicycles", "concept_group": "md-069", "img": "img/md-069.webp"}, {"id": "md-070", "category": "Turns", "question": "You approach a roundabout with traffic already circulating. What should you do?", "answer": "Yield to circulating traffic and enter when safe", "choices": ["Yield to circulating traffic and enter when safe", "Enter without yielding because entering cars have priority", "Stop in the circle to check directions", "Drive clockwise around the center"], "explanation": "Yield to traffic already in the roundabout and follow its direction.", "manual_ref": "Sec. 5.I Roundabouts", "concept_group": "roundabout-entry", "img": "img/md-070.webp"}, {"id": "md-071", "category": "Rail", "question": "A train is approaching a crossing, but the gates are not yet fully down. What should you do?", "answer": "Stop and wait; never try to beat the train", "choices": ["Stop and wait; never try to beat the train", "Cross quickly if your car is small", "Drive around the gate", "Stop only if a horn is sounding"], "explanation": "Trains cannot swerve and take a long distance to stop.", "manual_ref": "Sec. 5.G Highway-Railroad Crossings", "concept_group": "rail-gates", "img": "img/md-071.webp"}, {"id": "md-072", "category": "Rail", "question": "Your vehicle becomes stuck on railroad tracks and a train may be approaching. What should you do?", "answer": "Get everyone out and away from the tracks and call emergency services", "choices": ["Get everyone out and away from the tracks and call emergency services", "Remain inside and try restarting indefinitely", "Stand next to the vehicle", "Wave down the train from the tracks"], "explanation": "Evacuate immediately and move to a safe location away from the tracks.", "manual_ref": "Sec. 5.G Highway-Railroad Crossings", "concept_group": "stuck-on-tracks", "img": "img/md-072.webp"}, {"id": "md-073", "category": "Rail", "question": "You are behind a truck stopped at a railroad crossing. What is the safest assumption?", "answer": "It may need to stop for tracks even if signals are not active", "choices": ["It may need to stop for tracks even if signals are not active", "It must be broken down", "You should pass on the tracks", "Trucks never stop at crossings"], "explanation": "Some vehicles are required to stop at railroad crossings; leave room.", "manual_ref": "Sec. 5.G Highway-Railroad Crossings", "concept_group": "md-073", "img": "img/md-073.webp"}, {"id": "md-074", "category": "Awareness", "question": "A ball rolls into the road between parked cars. What should you anticipate?", "answer": "A child may run after it", "choices": ["A child may run after it", "No hazard once the ball stops", "Only a dog could follow", "The ball will always roll away"], "explanation": "Predict hidden hazards and slow enough to react.", "manual_ref": "Sec. 3.A Drive Defensively", "concept_group": "md-074", "img": "img/md-074.webp"}, {"id": "md-075", "category": "Awareness", "question": "You approach a green light but traffic is backed up beyond the intersection. What should you do?", "answer": "Wait until there is space to clear the intersection", "choices": ["Wait until there is space to clear the intersection", "Enter and stop in the crosswalk", "Use the horn to make room", "Turn without signaling"], "explanation": "Do not block an intersection even when your light is green.", "manual_ref": "Sec. 3.A Drive Defensively", "concept_group": "gridlock", "img": "img/md-075.webp"}, {"id": "md-076", "category": "Awareness", "question": "An approaching car is drifting over the centerline. What is the best first response?", "answer": "Reduce speed, create space and prepare to avoid a collision", "choices": ["Reduce speed, create space and prepare to avoid a collision", "Hold your position and accelerate", "Flash high beams continuously and move closer", "Cross the centerline to challenge the driver"], "explanation": "Defensive driving prioritizes space and escape options.", "manual_ref": "Sec. 3.A Drive Defensively", "concept_group": "md-076", "img": "img/md-076.webp"}, {"id": "md-077", "category": "Awareness", "question": "You hear a siren but cannot locate the emergency vehicle. What should you do?", "answer": "Slow, scan and be prepared to yield safely", "choices": ["Slow, scan and be prepared to yield safely", "Make an abrupt left turn", "Accelerate to outrun it", "Ignore it until the vehicle is visible"], "explanation": "Locate the hazard and create room without making unpredictable moves.", "manual_ref": "Sec. 3.A Drive Defensively", "concept_group": "md-077", "img": "img/md-077.webp"}, {"id": "md-078", "category": "Awareness", "question": "Your GPS tells you to turn where a sign prohibits the turn. What should you do?", "answer": "Obey the sign and find a legal alternate route", "choices": ["Obey the sign and find a legal alternate route", "Follow the GPS because it has current maps", "Turn if nobody is watching", "Stop in the intersection to reset the GPS"], "explanation": "Traffic controls take precedence over navigation instructions.", "manual_ref": "Sec. 3.A Drive Defensively", "concept_group": "md-078", "img": "img/md-078.webp"}, {"id": "md-079", "category": "Awareness", "question": "A car signals a lane change but the adjacent lane is occupied. What does signaling allow?", "answer": "Nothing until the driver confirms a safe opening", "choices": ["Nothing until the driver confirms a safe opening", "An automatic right-of-way", "Other cars must stop", "Permission to cross a solid barrier"], "explanation": "Signaling warns others; it does not make an unsafe maneuver legal.", "manual_ref": "Sec. 3.A Drive Defensively", "concept_group": "md-079", "img": "img/md-079.webp"}, {"id": "md-080", "category": "Awareness", "question": "You are approaching a hillcrest with limited sight distance. Is passing appropriate?", "answer": "No, wait until you have adequate visibility and a legal passing zone", "choices": ["No, wait until you have adequate visibility and a legal passing zone", "Yes, if your car accelerates quickly", "Yes, if you flash headlights", "Yes, if the vehicle ahead is slow"], "explanation": "Never pass where you cannot see enough clear road ahead.", "manual_ref": "Sec. 3.I Passing", "concept_group": "md-080", "img": "img/md-080.webp"}, {"id": "md-081", "category": "Awareness", "question": "A vehicle ahead stops for a pedestrian at a crosswalk. What should you do?", "answer": "Stop and do not pass the stopped vehicle", "choices": ["Stop and do not pass the stopped vehicle", "Pass on the right if there is room", "Honk until the driver moves", "Move around on the left without slowing"], "explanation": "The stopped vehicle may conceal a pedestrian in the crossing.", "manual_ref": "Sec. 7.A Pedestrian Right-of-Way", "concept_group": "crosswalk", "img": "img/md-081.webp"}, {"id": "md-083", "category": "Awareness", "question": "You notice a vehicle in your blind spot while preparing to merge. What should you do?", "answer": "Wait or adjust speed until a safe gap opens", "choices": ["Wait or adjust speed until a safe gap opens", "Merge because your signal is on", "Brake sharply in the travel lane", "Force the other driver onto the shoulder"], "explanation": "A safe gap is required regardless of signaling.", "manual_ref": "Sec. 3.A Drive Defensively", "concept_group": "blind-spot", "img": "img/md-083.webp"}, {"id": "md-085", "category": "Awareness", "question": "An animal runs across a rural road at night. What is the safest response?", "answer": "Brake firmly while maintaining control and avoid an unsafe swerve", "choices": ["Brake firmly while maintaining control and avoid an unsafe swerve", "Swerve sharply into opposing traffic", "Accelerate to pass behind it", "Close your eyes and hold the wheel"], "explanation": "Maintain control and avoid steering into a more serious collision.", "manual_ref": "Sec. 3.A Drive Defensively", "concept_group": "animal", "img": "img/md-085.webp"}, {"id": "md-086", "category": "Signs", "question": "At a stop sign with no stop line or crosswalk, where must you stop?", "answer": "Before entering the intersecting roadway", "choices": ["Before entering the intersecting roadway", "After your front wheels enter the intersection", "Beside the stop sign regardless of sight lines", "Only after another vehicle appears"], "explanation": "Stop before entering the intersection and yield before moving.", "manual_ref": "Sec. 4.B Traffic Signs", "concept_group": "md-086", "img": "img/md-086.webp"}, {"id": "md-087", "category": "Signals", "question": "You are stopped at a red light and want to turn right. A NO TURN ON RED sign is posted. What is legal?", "answer": "Wait for a signal permitting the turn", "choices": ["Wait for a signal permitting the turn", "Turn after stopping if the crosswalk is empty", "Turn if a driver behind you honks", "Turn if you signal for three seconds"], "explanation": "The posted prohibition overrides the usual permission to turn right on red.", "manual_ref": "Sec. 4.A Traffic Signals", "concept_group": "md-087", "img": "img/md-087.webp"}, {"id": "md-089", "category": "Signals", "question": "A lane-control signal above your lane shows a red X. What does it mean?", "answer": "Do not drive in that lane", "choices": ["Do not drive in that lane", "The lane is for passing only", "The lane is open if traffic is light", "You may use the lane to turn left"], "explanation": "A red X marks a closed lane.", "manual_ref": "Sec. 4.A.10 Lane Use Signals", "concept_group": "md-089", "img": "img/md-089.webp"}, {"id": "md-090", "category": "Signals", "question": "A lane-control signal shows a green downward arrow. What does it indicate?", "answer": "The lane is open for travel", "choices": ["The lane is open for travel", "Stop in the lane", "The lane is reserved for emergency vehicles", "Make a U-turn from that lane"], "explanation": "A green downward arrow identifies an available lane.", "manual_ref": "Sec. 4.A.10 Lane Use Signals", "concept_group": "md-090", "img": "img/md-090.webp"}, {"id": "md-091", "category": "Signs", "question": "You see a yellow sign showing two arrows pointing in opposite directions. What is ahead?", "answer": "Two-way traffic", "choices": ["Two-way traffic", "A one-way street", "A divided highway begins", "Passing is required"], "explanation": "Two opposite arrows warn of traffic moving in both directions.", "manual_ref": "Sec. 4.B Traffic Signs", "concept_group": "md-091", "img": "img/md-091.webp"}, {"id": "md-092", "category": "Signs", "question": "A yellow diamond shows a car with wavy tire tracks. What does it warn?", "answer": "Slippery roadway conditions", "choices": ["Slippery roadway conditions", "A winding detour only", "A car wash ahead", "Loose steering is required"], "explanation": "The skid symbol warns that the pavement may be slippery.", "manual_ref": "Sec. 4.B Traffic Signs", "concept_group": "md-092", "img": "img/md-092.webp"}, {"id": "md-093", "category": "Signs", "question": "A yellow diamond shows a black curved arrow and an advisory 25 MPH plaque. What does 25 MPH mean?", "answer": "Recommended safe speed for the curve under favorable conditions", "choices": ["Recommended safe speed for the curve under favorable conditions", "The minimum legal speed on the road", "The speed limit for the entire county", "A requirement to accelerate to 25 MPH"], "explanation": "An advisory plaque recommends a speed for the specific hazard.", "manual_ref": "Sec. 4.B Traffic Signs", "concept_group": "curve-speed", "img": "img/md-093.webp"}, {"id": "md-094", "category": "Signs", "question": "You see a DO NOT ENTER sign facing your vehicle at a ramp. What should you do?", "answer": "Do not enter the ramp", "choices": ["Do not enter the ramp", "Enter if there is no opposing traffic", "Stop and then proceed", "Use the ramp only during daylight"], "explanation": "The sign indicates traffic must not enter from your direction.", "manual_ref": "Sec. 4.B Traffic Signs", "concept_group": "md-094", "img": "img/md-094.webp"}, {"id": "md-095", "category": "Signs", "question": "A WRONG WAY sign appears ahead. What does it mean?", "answer": "You are traveling against the permitted direction", "choices": ["You are traveling against the permitted direction", "The road is closed for construction only", "You must turn left at the next light", "The speed limit has changed"], "explanation": "Stop safely and correct your route without continuing against traffic.", "manual_ref": "Sec. 4.B Traffic Signs", "concept_group": "md-095", "img": "img/md-095.webp"}, {"id": "md-096", "category": "Right-of-way", "question": "You are turning right across a sidewalk into a parking lot while someone is walking on the sidewalk. Who goes first?", "answer": "The pedestrian on the sidewalk", "choices": ["The pedestrian on the sidewalk", "The turning vehicle", "Whichever is moving faster", "The vehicle if its turn signal is on"], "explanation": "Turning drivers must yield to pedestrians crossing the driveway.", "manual_ref": "Sec. 7.A Pedestrian Right-of-Way", "concept_group": "md-096", "img": "img/md-096.webp"}, {"id": "md-098", "category": "Right-of-way", "question": "You miss your exit in a roundabout. What is the safest action?", "answer": "Continue around and take the exit on the next circuit", "choices": ["Continue around and take the exit on the next circuit", "Stop and reverse to the exit", "Cut across the center island", "Make a U-turn against traffic"], "explanation": "Continue with the traffic flow rather than reversing or cutting across lanes.", "manual_ref": "Sec. 5.I Roundabouts", "concept_group": "roundabout-exit", "img": "img/md-098.webp"}, {"id": "md-099", "category": "Right-of-way", "question": "At an all-way stop, you and the vehicle opposite arrive simultaneously. You are turning left; it is going straight. Who yields?", "answer": "You yield to the straight-moving vehicle", "choices": ["You yield to the straight-moving vehicle", "The straight-moving vehicle yields to you", "The vehicle with the louder horn yields", "Neither vehicle needs to yield"], "explanation": "At the same arrival time, a left turn yields to opposing straight traffic.", "manual_ref": "Sec. 3.B Right-of-Way", "concept_group": "four-way-stop", "img": "img/md-099.webp"}, {"id": "md-101", "category": "Right-of-way", "question": "You approach a stopped school bus with flashing red lights on the opposite side of a highway separated by a physical median. What is generally required?", "answer": "You do not have to stop if the bus is on the other side of a physical barrier", "choices": ["You do not have to stop if the bus is on the other side of a physical barrier", "Stop at least 20 feet from the bus", "Stop only if children are visible", "Pass the bus at any speed"], "explanation": "On a multiple-lane road divided by a physical barrier, you do not stop for a school bus on the other side of the barrier. Still drive with caution.", "manual_ref": "Sec. 7.D School Buses", "concept_group": "school-bus-stop", "img": "img/md-101.webp"}, {"id": "md-102", "category": "Right-of-way", "question": "An ambulance, tow truck or other vehicle is stopped on the shoulder with its lights flashing. What does the Move Over Law require?", "answer": "Move to a lane not next to it, or slow to a safe speed if you cannot move over", "choices": ["Move to a lane not next to it, or slow to a safe speed if you cannot move over", "Stay in the adjacent lane at full speed", "Stop in the travel lane beside it", "Move onto the shoulder behind it"], "explanation": "Maryland's Move Over Law applies to any vehicle stopped, standing or parked on the road with its lights flashing. Move over if you can; if not, slow to a safe speed.", "manual_ref": "Sec. 8.D Move Over Law", "concept_group": "move-over", "img": "img/md-102.webp"}, {"id": "md-103", "category": "Road markings", "question": "A center lane is marked with left-turn arrows for traffic from both directions. How should it be used?", "answer": "Only for preparing to make a permitted left turn", "choices": ["Only for preparing to make a permitted left turn", "For passing slow vehicles", "As an ordinary travel lane", "For parking during rush hour"], "explanation": "A shared center turn lane is for left turns, not passing or through travel.", "manual_ref": "Sec. 4.A.10 / 4.B Two-way Left", "concept_group": "md-103", "img": "img/md-103.webp"}, {"id": "md-104", "category": "Road markings", "question": "A solid yellow line is next to a broken yellow line. The solid line is on your side. Can you cross to pass?", "answer": "No, passing across the centerline is prohibited from your side", "choices": ["No, passing across the centerline is prohibited from your side", "Yes, because the other side has a broken line", "Yes, if you sound your horn", "Only when following a truck"], "explanation": "Passing permission depends on the line on your side.", "manual_ref": "Sec. 3.I Passing", "concept_group": "md-104", "img": "img/md-104.webp"}, {"id": "md-108", "category": "Speed", "question": "At night, what limits how far ahead you can see hazards?", "answer": "Your headlights; drive at a speed that lets you stop within what you can see", "choices": ["Your headlights; drive at a speed that lets you stop within what you can see", "Nothing, if streetlights are on", "Your mirrors", "The speed limit"], "explanation": "At night you can see only as far as your headlights allow, so slow down, increase following distance, and use high beams where appropriate.", "manual_ref": "Sec. 5.B Driving at Night", "concept_group": "md-108", "img": "img/md-108.webp"}, {"id": "md-114", "category": "Parking", "question": "You are backing out of a parking space. What is the safest method?", "answer": "Check all around, look behind, and reverse slowly while yielding", "choices": ["Check all around, look behind, and reverse slowly while yielding", "Rely entirely on the backup camera", "Back quickly to minimize time in the aisle", "Assume pedestrians will stop for you"], "explanation": "Cameras supplement, but do not replace, direct observation and yielding.", "manual_ref": "Sec. 10.L Back-In Parking", "concept_group": "md-114", "img": "img/md-114.webp"}, {"id": "md-115", "category": "Awareness", "question": "A vehicle beside you disappears from both your forward view and mirrors. What should you do before changing lanes?", "answer": "Check the blind spot over your shoulder", "choices": ["Check the blind spot over your shoulder", "Change lanes quickly before it returns", "Honk and steer immediately", "Look only at the dashboard display"], "explanation": "Blind-spot checks are necessary even when mirrors appear clear.", "manual_ref": "Sec. 3.A Drive Defensively", "concept_group": "blind-spot", "img": "img/md-115.webp"}, {"id": "md-116", "category": "Awareness", "question": "A driver is using a phone while stopped at a red light. What is the safest rule to follow?", "answer": "Keep attention on driving and avoid prohibited handheld phone use", "choices": ["Keep attention on driving and avoid prohibited handheld phone use", "Text because the vehicle is not moving", "Use both hands on the phone while waiting", "Check messages as soon as the light turns yellow"], "explanation": "Distraction is dangerous even at intersections and Maryland restricts handheld device use.", "manual_ref": "Sec. 6.C Distracted Driving", "concept_group": "phone", "img": "img/md-116.webp"}, {"id": "md-117", "category": "Awareness", "question": "You pass a yellow deer-crossing warning sign at dusk. What is safest?", "answer": "Slow down and watch for additional animals", "choices": ["Slow down and watch for additional animals", "Accelerate past it immediately", "Honk continuously while speeding up", "Swerve into the opposite lane in advance"], "explanation": "Warning signs alert you to hazards ahead. Slow down and watch for deer and other wildlife, which often travel in groups.", "manual_ref": "Sec. 4.B Warning Signs", "concept_group": "animal", "img": "img/md-117.webp"}, {"id": "md-118", "category": "Awareness", "question": "You approach a railroad crossing and the gates begin lowering. What should you do?", "answer": "Stop before the crossing and wait for the gates to rise and signals to end", "choices": ["Stop before the crossing and wait for the gates to rise and signals to end", "Drive around the gate if no train is visible", "Stop on the tracks and look both ways", "Accelerate through as the gate lowers"], "explanation": "Never go around or under a lowered crossing gate.", "manual_ref": "Sec. 5.G Highway-Railroad Crossings", "concept_group": "rail-gates", "img": "img/md-118.webp"}, {"id": "md-126", "category": "Sharing", "question": "A motorcycle is riding near the left side of its lane. What should you assume?", "answer": "The motorcycle is entitled to use the full lane", "choices": ["The motorcycle is entitled to use the full lane", "The rider invites you to share the lane", "The motorcycle must move onto the shoulder", "The rider is turning left without signaling"], "explanation": "Motorcycles have the same right to lane space as other vehicles.", "manual_ref": "Sec. 7.E Motorcycles", "concept_group": "md-126", "img": "img/md-126.webp"}, {"id": "md-127", "category": "Sharing", "question": "A large truck begins a right turn and moves left before turning. What should you do?", "answer": "Stay back and do not squeeze into the space on its right", "choices": ["Stay back and do not squeeze into the space on its right", "Pass quickly on its right", "Pull beside its rear wheels", "Assume the truck is changing lanes left"], "explanation": "Large vehicles may swing wide; avoid their right-side blind area.", "manual_ref": "Sec. 7.C Large Trucks and Buses", "concept_group": "md-127", "img": "img/md-127.webp"}, {"id": "md-130", "category": "Work zones", "question": "A flagger in a work zone signals you to stop although the temporary sign says SLOW. What should you do?", "answer": "Stop and follow the flagger’s direction", "choices": ["Stop and follow the flagger’s direction", "Follow the sign instead", "Continue at the posted speed", "Drive around the flagger"], "explanation": "Authorized flaggers direct traffic through work zones.", "manual_ref": "Sec. 5.H Work Zone Safety", "concept_group": "flagger", "img": "img/md-130.webp"}, {"id": "md-131", "category": "Work zones", "question": "Orange cones narrow two lanes into one ahead. When should you merge?", "answer": "Merge safely as directed by signs and traffic conditions", "choices": ["Merge safely as directed by signs and traffic conditions", "Wait until you hit the first cone", "Drive through the closed lane", "Stop in the middle of both lanes"], "explanation": "Watch advance warnings and merge in a predictable, lawful way.", "manual_ref": "Sec. 5.H Work Zone Safety", "concept_group": "md-131", "img": "img/md-131.webp"}, {"id": "md-132", "category": "Work zones", "question": "A construction worker is standing near the edge of your travel lane. What should you do?", "answer": "Slow down and allow extra clearance", "choices": ["Slow down and allow extra clearance", "Maintain speed because cones provide protection", "Honk and drive closer to the cones", "Focus on the navigation screen"], "explanation": "Work zones require heightened attention and reduced speed when conditions demand.", "manual_ref": "Sec. 5.H Work Zone Safety", "concept_group": "md-132", "img": "img/md-132.webp"}, {"id": "md-135", "category": "Impairment", "question": "You are the designated driver at a party. What is the safest plan?", "answer": "Avoid alcohol and other impairing substances before driving", "choices": ["Avoid alcohol and other impairing substances before driving", "Have one drink if you feel fine", "Drive only on familiar roads after drinking", "Wait until you no longer smell alcohol"], "explanation": "Impairment can occur before a driver feels intoxicated.", "manual_ref": "Sec. 6.A Alcohol, Drugs and Driving", "concept_group": "impaired-friend", "img": "img/md-135.webp"}, {"id": "md-140", "category": "Vehicle control", "question": "You are in the left lane of a multilane road but driving slower than traffic. What is safest?", "answer": "Move right when safe and lawful", "choices": ["Move right when safe and lawful", "Remain left to control everyone’s speed", "Brake to make traffic slow down", "Weave between lanes"], "explanation": "Keep right when appropriate and avoid obstructing traffic.", "manual_ref": "Sec. 5.J Interstate Driving", "concept_group": "keep-right", "img": "img/md-140.webp"}, {"id": "md-141", "category": "Vehicle control", "question": "A traffic light changes to yellow while you are already lawfully in the intersection. What should you do?", "answer": "Continue to clear the intersection safely", "choices": ["Continue to clear the intersection safely", "Reverse behind the stop line", "Stop immediately in the middle", "Accelerate aggressively"], "explanation": "Clear the intersection safely without abrupt maneuvers.", "manual_ref": "Sec. 3 Basic Driving", "concept_group": "md-141", "img": "img/md-141.webp"}, {"id": "md-144", "category": "Vehicle control", "question": "During hard braking, your brake pedal vibrates and you hear a rumble. What does this mean in a car with ABS?", "answer": "The ABS is rapidly pumping the brakes to keep the wheels from locking", "choices": ["The ABS is rapidly pumping the brakes to keep the wheels from locking", "The brakes have failed", "You should pump the pedal yourself", "You should release the brake immediately"], "explanation": "ABS pumps the brakes much faster than you can to prevent wheel lock-up. A rumble and a vibrating pedal are normal when it engages.", "manual_ref": "Sec. 10.I ABS", "concept_group": "md-144", "img": "img/md-144.webp"}, {"id": "md-145", "category": "Signs", "question": "A yellow pennant-shaped (sideways triangle) sign is on the left side of the road. What does it mark?", "answer": "The start of a no-passing zone", "choices": ["The start of a no-passing zone", "A school zone ahead", "A yield point for merging traffic", "The end of a work zone"], "explanation": "The pennant shape marks the start of a no-passing zone. Do not pass other vehicles.", "manual_ref": "Sec. 4.B Colors & Shapes", "concept_group": "no-passing-pennant", "img": "img/md-145.webp"}, {"id": "md-146", "category": "Signs", "question": "A white X-shaped crossbuck sign stands beside the road. What does it identify?", "answer": "The location of a railroad crossing", "choices": ["The location of a railroad crossing", "A four-way stop", "A closed lane ahead", "A pedestrian crossing"], "explanation": "The crossbuck identifies the location of a highway-rail grade crossing. Look, listen, and be ready to stop for trains.", "manual_ref": "Sec. 4.B Colors & Shapes", "concept_group": "crossbuck", "img": "img/md-146.webp"}, {"id": "md-147", "category": "Signs", "question": "You see a fluorescent pink sign. What does the color pink indicate?", "answer": "An emergency traffic incident", "choices": ["An emergency traffic incident", "A school zone", "Recreation and cultural areas", "Gas, food and lodging services"], "explanation": "Fluorescent pink signs are used for emergency traffic incidents.", "manual_ref": "Sec. 4.B Colors & Shapes", "concept_group": "sign-color-pink", "img": "img/md-147.webp"}, {"id": "md-148", "category": "Signs", "question": "A brown sign appears along the highway. What kind of information does it usually give?", "answer": "Directions to recreation or cultural interest areas", "choices": ["Directions to recreation or cultural interest areas", "A warning about a hazard", "Speed limits", "Work zone conditions"], "explanation": "Brown signs point to recreation and cultural interest areas.", "manual_ref": "Sec. 4.B Colors & Shapes", "concept_group": "sign-color-brown", "img": "img/md-148.webp"}, {"id": "md-149", "category": "Signs", "question": "A blue sign appears along the highway. What does it usually show?", "answer": "Services such as food, gas and rest areas", "choices": ["Services such as food, gas and rest areas", "Regulatory rules you must obey", "Emergency incidents", "School crossings"], "explanation": "Blue signs show motorist services like food, gas and rest areas.", "manual_ref": "Sec. 4.B Colors & Shapes", "concept_group": "sign-color-blue", "img": "img/md-149.webp"}, {"id": "md-150", "category": "Signs", "question": "A yellow warning sign shows a school bus with the words STOP AHEAD. What should you expect?", "answer": "A school bus stop ahead; be prepared to stop", "choices": ["A school bus stop ahead; be prepared to stop", "Buses may not stop on this road", "A bus-only lane begins", "You must stop immediately at the sign"], "explanation": "This warning sign alerts you that a school bus may be stopped ahead. Slow down and be ready to stop if its red lights flash.", "manual_ref": "Sec. 4.B Warning Signs", "concept_group": "school-bus-ahead-sign", "img": "img/md-150.webp"}, {"id": "md-151", "category": "Signs", "question": "A farm tractor ahead has an orange-red triangle on its back. What does the triangle mean?", "answer": "It is a slow-moving vehicle going 25 mph or less", "choices": ["It is a slow-moving vehicle going 25 mph or less", "It is carrying hazardous materials", "It is about to turn left", "It is an emergency vehicle"], "explanation": "The slow-moving vehicle emblem warns that the vehicle travels 25 mph or less. Adjust your speed and pass only when it is safe.", "manual_ref": "Sec. 5.L Slow Moving Vehicles", "concept_group": "slow-moving-vehicle", "img": "img/md-151.webp"}, {"id": "md-152", "category": "Signals", "question": "A steady yellow arrow appears for your turn lane. What does it mean?", "answer": "Permission to turn in that direction is ending", "choices": ["Permission to turn in that direction is ending", "You may turn without yielding", "Turns are allowed only for buses", "The signal is broken"], "explanation": "A steady yellow arrow means permission to turn in that direction is ending. Slow down and proceed with caution, or stop if you safely can.", "manual_ref": "Sec. 4.A.5 Steady Yellow Arrow", "concept_group": "yellow-arrow", "img": "img/md-152.webp"}, {"id": "md-153", "category": "Signals", "question": "A flashing red arrow points right at your intersection. What should you do?", "answer": "Stop completely, yield, then turn right when the way is clear", "choices": ["Stop completely, yield, then turn right when the way is clear", "Turn right without stopping", "Wait until the arrow turns green", "Treat it as a flashing yellow arrow"], "explanation": "At a flashing red arrow, come to a complete stop, yield to all traffic and pedestrians, and then proceed in the direction of the arrow when the way is clear.", "manual_ref": "Sec. 4.A.9 Flashing Red Arrow", "concept_group": "flashing-red-arrow", "img": "img/md-153.webp"}, {"id": "md-154", "category": "Signals", "question": "A steady yellow X appears over your lane. What should you do?", "answer": "Move out of that lane as soon as you safely can", "choices": ["Move out of that lane as soon as you safely can", "Stay in the lane and speed up", "Stop in the lane immediately", "Use the lane only to pass"], "explanation": "A steady yellow X on a lane use signal means move out of that lane as soon as it is safe.", "manual_ref": "Sec. 4.A.10 Lane Use Signals", "concept_group": "lane-yellow-x", "img": "img/md-154.webp"}, {"id": "md-155", "category": "Signals", "question": "A flashing yellow X appears over a center lane. How may you use it?", "answer": "Only for a left turn, possibly shared with opposite-direction left turns", "choices": ["Only for a left turn, possibly shared with opposite-direction left turns", "For passing at any time", "For through travel at full speed", "It is closed to all traffic"], "explanation": "A flashing yellow X or two-way left-turn arrows mean you may use the lane for a left turn. Drivers from the opposite direction may also be turning left there.", "manual_ref": "Sec. 4.A.10 Lane Use Signals", "concept_group": "lane-flashing-yellow-x", "img": "img/md-155.webp"}, {"id": "md-156", "category": "Rail", "question": "A flashing red signal is operating at a railroad crossing, but you see no train. What must you do?", "answer": "Stop completely and wait until the light stops flashing and the way is clear", "choices": ["Stop completely and wait until the light stops flashing and the way is clear", "Slow down and cross if no train is visible", "Stop only if gates are down", "Honk and proceed"], "explanation": "At a flashing red signal at a railroad crossing, you must come to a complete stop even if you do not see a train.", "manual_ref": "Sec. 4.A.7 Flashing Red Signal", "concept_group": "rail-flashing-red", "img": "img/md-156.webp"}, {"id": "md-157", "category": "Rail", "question": "A train has just passed the crossing and the gates rise. What should you do before crossing?", "answer": "Look both ways, because another train may be coming on another track", "choices": ["Look both ways, because another train may be coming on another track", "Cross immediately", "Follow the train closely", "Speed across before the gates lower again"], "explanation": "After a train passes, look both ways and make sure the tracks are clear. Another train may be coming on another track.", "manual_ref": "Sec. 5.G Highway-Railroad Crossings", "concept_group": "rail-second-train", "img": "img/md-157.webp"}, {"id": "md-158", "category": "Signals", "question": "A uniformed school crossing guard signals you to stop while your traffic light is green. What should you do?", "answer": "Stop and follow the crossing guard", "choices": ["Stop and follow the crossing guard", "Proceed because the light is green", "Honk and continue slowly", "Stop only if children are already in the road"], "explanation": "You must follow a uniformed school crossing guard who is directing traffic near a school, even if a signal shows something different.", "manual_ref": "Sec. 4 Traffic Control Devices", "concept_group": "crossing-guard", "img": "img/md-158.webp"}, {"id": "md-159", "category": "Signals", "question": "At a pedestrian crosswalk signal, your signal is flashing yellow. What should you do?", "answer": "Slow down and be ready to yield to pedestrians", "choices": ["Slow down and be ready to yield to pedestrians", "Speed up before it turns red", "Stop and remain stopped", "Ignore it unless you see a pedestrian in the road"], "explanation": "At a pedestrian crosswalk signal, a flashing yellow light tells drivers to slow down and yield to pedestrians who may be crossing.", "manual_ref": "Sec. 4.A Crosswalk Signals", "concept_group": "ped-signal", "img": "img/md-159.webp"}, {"id": "md-160", "category": "Right-of-way", "question": "You are turning left at an intersection and a motorcycle is approaching from the opposite direction. What should you do?", "answer": "Yield to the motorcycle", "choices": ["Yield to the motorcycle", "Turn quickly before it arrives", "Flash your lights and turn", "Proceed, since motorcycles must yield to cars"], "explanation": "Yield the right-of-way to an oncoming motorcycle when turning left. Drivers are at fault in over half of car-motorcycle crashes.", "manual_ref": "Sec. 7.E Motorcycles", "concept_group": "moto-left-turn", "img": "img/md-160.webp"}, {"id": "md-161", "category": "Right-of-way", "question": "A funeral procession with headlights and hazard lights on is going through an intersection while your light is green. What should you do?", "answer": "Yield until the procession has passed", "choices": ["Yield until the procession has passed", "Proceed because your light is green", "Join the procession", "Honk so the procession stops"], "explanation": "Even with a green signal, other drivers must yield to a funeral procession until all of its vehicles have passed.", "manual_ref": "Sec. 5.K Funeral Processions", "concept_group": "funeral", "img": "img/md-161.webp"}, {"id": "md-162", "category": "Right-of-way", "question": "An emergency vehicle using its lights and siren is ahead of you, going the same direction. When may you pass it?", "answer": "Only if it stops or a police officer tells you to pass", "choices": ["Only if it stops or a police officer tells you to pass", "Whenever the left lane is open", "When it slows below the speed limit", "Never, under any circumstances"], "explanation": "You may not pass an emergency vehicle using its signals in the same direction unless it stops or a police officer tells you to pass.", "manual_ref": "Sec. 7.B Emergency Vehicles", "concept_group": "emergency-pass", "img": "img/md-162.webp"}, {"id": "md-163", "category": "Right-of-way", "question": "A disabled car with hazard lights flashing is stopped on the shoulder. Does the Move Over Law apply?", "answer": "Yes; move over if you can, or slow to a safe speed if you cannot", "choices": ["Yes; move over if you can, or slow to a safe speed if you cannot", "No, it applies only to police vehicles", "Only on interstate highways", "Only at night"], "explanation": "In Maryland, you must move over for any vehicle stopped, standing or parked on the road with its lights flashing. If you cannot move over, slow to a safe speed.", "manual_ref": "Sec. 8.D Move Over Law", "concept_group": "move-over", "img": "img/md-163.webp"}, {"id": "md-164", "category": "Space", "question": "You have just passed a car. When is it safe to return to your original lane?", "answer": "When you can see both of its headlights in your rear-view mirror", "choices": ["When you can see both of its headlights in your rear-view mirror", "As soon as your rear bumper clears its front bumper", "After counting one second", "When the other driver flashes the high beams"], "explanation": "See both headlights of the passed vehicle in your rear-view mirror before returning to the lane you came from.", "manual_ref": "Sec. 3.I Passing", "concept_group": "pass-return", "img": "img/md-164.webp"}, {"id": "md-165", "category": "Space", "question": "When may you pass another vehicle on the right?", "answer": "When it is about to turn left and you can pass safely without leaving the road", "choices": ["When it is about to turn left and you can pass safely without leaving the road", "Whenever the right shoulder is clear", "Whenever traffic is slow", "Never"], "explanation": "Pass on the left in most cases. Passing on the right is allowed when it is safe, you stay on the road, and, for example, the vehicle ahead is about to turn left.", "manual_ref": "Sec. 3.I Passing", "concept_group": "pass-right", "img": "img/md-165.webp"}, {"id": "md-166", "category": "Sharing", "question": "How far does a large truck's right-side blind spot extend?", "answer": "The length of the trailer and out as far as three lanes", "choices": ["The length of the trailer and out as far as three lanes", "Only a few feet beside the cab", "Only directly behind the truck", "It has no right-side blind spot"], "explanation": "The right-side No-Zone runs the length of the trailer and extends out three lanes. If you cannot see the driver's face in the mirror, the driver cannot see you.", "manual_ref": "Sec. 7.C Large Trucks and Buses", "concept_group": "truck-right-nozone", "img": "img/md-166.webp"}, {"id": "md-167", "category": "Sharing", "question": "You are passing a bicyclist riding in a marked bike lane. How much space must you leave?", "answer": "At least 3 feet, even when the bicyclist is in a bike lane", "choices": ["At least 3 feet, even when the bicyclist is in a bike lane", "No space is required in a bike lane", "1 foot", "Only enough to avoid touching"], "explanation": "Leave at least 3 feet when passing a bicycle in a bike lane, on the shoulder or in your lane.", "manual_ref": "Sec. 7.F Bicycles", "concept_group": "bike-pass", "img": "img/md-167.webp"}, {"id": "md-168", "category": "Sharing", "question": "A pedestrian is crossing at an unmarked crosswalk at an intersection with no signal. What must you do?", "answer": "Stop and let the pedestrian cross", "choices": ["Stop and let the pedestrian cross", "Proceed because the crosswalk is not marked", "Honk to warn the pedestrian", "Swerve around the pedestrian"], "explanation": "Most intersections have a crosswalk even if it is not marked. When there is no signal, stop for pedestrians in a marked or unmarked crosswalk.", "manual_ref": "Sec. 7.A Pedestrian Right-of-Way", "concept_group": "unmarked-crosswalk", "img": "img/md-168.webp"}, {"id": "md-169", "category": "Weather", "question": "The fog is so thick that you cannot drive safely. What does the manual tell you to do?", "answer": "Pull completely off the road to a safe place and turn on your emergency flashers", "choices": ["Pull completely off the road to a safe place and turn on your emergency flashers", "Stop in your lane and wait", "Switch to high beams and continue", "Follow the taillights ahead closely"], "explanation": "If fog is so thick you cannot drive safely, pull completely off the road to a safe location and turn on your emergency flashers.", "manual_ref": "Sec. 5.C Driving in Fog", "concept_group": "fog-pull-off", "img": "img/md-169.webp"}, {"id": "md-170", "category": "Weather", "question": "What is black ice?", "answer": "A thin, hard-to-see layer of ice on asphalt caused by melting and refreezing", "choices": ["A thin, hard-to-see layer of ice on asphalt caused by melting and refreezing", "Ice that forms only on gravel roads", "Snow that has turned black from dirt", "Ice that is always easy to see at night"], "explanation": "Black ice is a thin layer of ice on blacktop that can be very hard or impossible to see. It forms when ice or snow melts and refreezes.", "manual_ref": "Sec. 5.D Inclement Weather", "concept_group": "black-ice", "img": "img/md-170.webp"}, {"id": "md-171", "category": "Weather", "question": "Your car does not have anti-lock brakes and you must slow on a slippery road. What does the manual advise?", "answer": "Pump the brakes to prevent skidding", "choices": ["Pump the brakes to prevent skidding", "Slam the brakes and hold them", "Use only the parking brake", "Shift into neutral and coast"], "explanation": "Avoid slamming on your brakes. If your vehicle does not have ABS, pump the brakes to prevent skidding.", "manual_ref": "Sec. 5.D Inclement Weather", "concept_group": "no-abs", "img": "img/md-171.webp"}, {"id": "md-172", "category": "Impairment", "question": "At what blood alcohol concentration does Maryland consider a driver to be under the influence?", "answer": ".08 or higher", "choices": [".08 or higher", ".15 or higher", ".20 or higher", "Only when the driver feels drunk"], "explanation": "Maryland considers drivers to be under the influence at a BAC of .08 or higher, but any amount of alcohol can affect your driving.", "manual_ref": "Sec. 6.A Alcohol, Drugs and Driving", "concept_group": "bac", "img": "img/md-172.webp"}, {"id": "md-173", "category": "Impairment", "question": "You are 19 and have had one beer. Is it legal for you to drive?", "answer": "No; drivers under 21 may not drink any alcohol", "choices": ["No; drivers under 21 may not drink any alcohol", "Yes, if you feel fine", "Yes, one drink is always legal", "Only if a passenger is 21"], "explanation": "If you are not yet 21, it is against the law to drink any alcohol. Your license can be suspended or revoked.", "manual_ref": "Sec. 6.A Under 21", "concept_group": "under-21", "img": "img/md-173.webp"}, {"id": "md-174", "category": "Impairment", "question": "A passenger has an open can of beer within reach. What is true?", "answer": "It is illegal to have an open alcohol container in the passenger area", "choices": ["It is illegal to have an open alcohol container in the passenger area", "It is legal if the driver is sober", "It is legal if the can is half empty", "It is legal in the back seat"], "explanation": "It is against the law to drive with an open container of alcohol in the passenger area, which includes any place the driver or passengers can easily reach.", "manual_ref": "Sec. 6.A Open Alcohol Container", "concept_group": "open-container", "img": "img/md-174.webp"}, {"id": "md-175", "category": "Impairment", "question": "What does Maryland's implied consent law mean?", "answer": "By driving, you agree to take an alcohol or drug test if an officer asks", "choices": ["By driving, you agree to take an alcohol or drug test if an officer asks", "You may refuse any test without consequence", "Only commercial drivers can be tested", "Tests are allowed only after a crash"], "explanation": "By driving on roads used by the public, you consent to take a drug or alcohol test if a law enforcement officer asks you to.", "manual_ref": "Sec. 9.B Implied Consent", "concept_group": "implied-consent", "img": "img/md-175.webp"}, {"id": "md-176", "category": "Impairment", "question": "Which of these is a danger sign of drowsy driving?", "answer": "You keep drifting out of your lane or cannot remember the last few miles", "choices": ["You keep drifting out of your lane or cannot remember the last few miles", "You feel alert after a full night of sleep", "You are hungry", "Your passengers are talking"], "explanation": "Danger signs include eyes closing, trouble keeping your head up, constant yawning, not remembering the last few miles, missing exits, and drifting out of your lane.", "manual_ref": "Sec. 6.D Drowsy Driving", "concept_group": "drowsy-signs", "img": "img/md-176.webp"}, {"id": "md-177", "category": "Awareness", "question": "Which is an example of aggressive driving?", "answer": "Tailgating and making unsafe lane changes", "choices": ["Tailgating and making unsafe lane changes", "Keeping a 4-second following distance", "Signaling before every turn", "Driving the speed limit"], "explanation": "Aggressive driving includes speeding, tailgating, ignoring traffic signals, unsafe lane changes, not yielding, and unsafe or illegal passing.", "manual_ref": "Sec. 6.B Aggressive Driving", "concept_group": "aggressive", "img": "img/md-177.webp"}, {"id": "md-178", "category": "Maryland", "question": "A driver under 25 has a learner's permit. How much supervised practice is required?", "answer": "At least 60 hours, including 10 hours at night", "choices": ["At least 60 hours, including 10 hours at night", "20 hours, all in daylight", "40 hours, with no night requirement", "No practice hours are required"], "explanation": "Applicants under 25 must practice at least 60 hours with a supervising driver, with at least 10 of those hours at night, and record them in the Practice and Skills Log.", "manual_ref": "Sec. 2.A Rookie Driver/GLS", "concept_group": "gls-hours", "img": "img/md-178.webp"}, {"id": "md-179", "category": "Maryland", "question": "You are 16 with a learner's permit. How long must you hold it before you can get a provisional license?", "answer": "At least 9 months without a violation", "choices": ["At least 9 months without a violation", "14 days", "45 days", "3 years"], "explanation": "Applicants under 18 must hold the Learner's Permit for at least 9 months without a violation before becoming eligible for a Provisional License.", "manual_ref": "Sec. 2.B Learner's Instructional Permit", "concept_group": "gls-hold", "img": "img/md-179.webp"}, {"id": "md-180", "category": "Maryland", "question": "Who may serve as your supervising driver while you hold a learner's permit?", "answer": "Someone at least 21, licensed at least 3 years, seated beside you", "choices": ["Someone at least 21, licensed at least 3 years, seated beside you", "Any licensed driver over 18", "Any passenger with a permit", "Anyone at least 16 seated in the back"], "explanation": "A supervising driver must be at least 21, licensed for at least three years to drive the same class of vehicle, and seated beside you.", "manual_ref": "Sec. 10.B Supervising Driver", "concept_group": "supervisor", "img": "img/md-180.webp"}, {"id": "md-181", "category": "Maryland", "question": "You are 17 and just got your provisional license. Who may ride with you when you drive unsupervised during the first 151 days?", "answer": "No passengers under 18 unless they are immediate family", "choices": ["No passengers under 18 unless they are immediate family", "Any friends, as long as they wear seat belts", "Up to three friends", "Only passengers under 16"], "explanation": "For the first 151 days, provisional drivers under 18 may not drive unsupervised with passengers under 18 unless they are immediate family members.", "manual_ref": "Sec. 9.A Passenger Restriction", "concept_group": "provisional-passengers", "img": "img/md-181.webp"}, {"id": "md-182", "category": "Maryland", "question": "A provisional license holder wants to drive alone at 1:00 a.m. When is that allowed?", "answer": "Only for work, an organized volunteer program, a school activity or an athletic event", "choices": ["Only for work, an organized volunteer program, a school activity or an athletic event", "Any time on weekends", "Never, under any circumstances", "Whenever a parent texts permission"], "explanation": "Provisional drivers may drive unsupervised between midnight and 5:00 a.m. only for a job, an organized volunteer program, an official school activity, or an athletic event they take part in.", "manual_ref": "Sec. 9.A Nighttime Restriction", "concept_group": "provisional-night", "img": "img/md-182.webp"}, {"id": "md-183", "category": "Maryland", "question": "Who in the vehicle must wear a seat belt or be in a child safety seat?", "answer": "The driver and all passengers", "choices": ["The driver and all passengers", "Only the driver", "Only front-seat passengers", "Only passengers under 16"], "explanation": "By law, the driver and all passengers must wear a safety belt or be buckled into a child safety seat.", "manual_ref": "Sec. 10.F Seat Belt Law", "concept_group": "seat-belt", "img": "img/md-183.webp"}, {"id": "md-184", "category": "Maryland", "question": "A 6-year-old who is 4 feet tall is riding in your car. What does Maryland law require?", "answer": "A child safety seat or booster seat", "choices": ["A child safety seat or booster seat", "A regular seat belt only", "The front seat with an air bag", "No restraint on short trips"], "explanation": "All children under age 8 must ride in a child safety seat unless they are 4 feet 9 inches or taller.", "manual_ref": "Sec. 10.G Child Safety Seats", "concept_group": "child-seat", "img": "img/md-184.webp"}, {"id": "md-185", "category": "Maryland", "question": "May you drive while wearing earbuds in both ears?", "answer": "No; earphones in both ears are prohibited, but hearing aids are allowed", "choices": ["No; earphones in both ears are prohibited, but hearing aids are allowed", "Yes, if the volume is low", "Yes, on highways only", "Yes, if you are using GPS"], "explanation": "You may not drive with earplugs, headsets or earphones in both ears. Hearing aid devices are allowed.", "manual_ref": "Sec. 10.J Headsets Prohibited", "concept_group": "earbuds", "img": "img/md-185.webp"}, {"id": "md-186", "category": "Emergencies", "question": "A police officer signals you to pull over. What should you do?", "answer": "Pull over away from traffic, turn on flashers, turn off the engine, stay in the car and keep your hands visible", "choices": ["Pull over away from traffic, turn on flashers, turn off the engine, stay in the car and keep your hands visible", "Get out and walk to the officer", "Keep driving to your destination", "Search the glove box before the officer arrives"], "explanation": "Pull off as far from traffic as possible, use flashers, turn off the engine and radio, stay in the vehicle with your seat belt on, and keep your hands in plain view.", "manual_ref": "Sec. 8.C Traffic Stops", "concept_group": "traffic-stop", "img": "img/md-186.webp"}, {"id": "md-187", "category": "Emergencies", "question": "Your car becomes disabled on a busy highway. Where should you try to stop?", "answer": "On the shoulder or, if you can reach it, an off-ramp or parking lot", "choices": ["On the shoulder or, if you can reach it, an off-ramp or parking lot", "In the painted triangle where the ramp exits", "In the travel lane with flashers on", "Under a bridge in the left lane"], "explanation": "Move a disabled vehicle as far from traffic as you can. Never stop or park in the triangular painted zones where a ramp exits the road.", "manual_ref": "Sec. 8.B Roadside Emergencies", "concept_group": "disabled-vehicle", "img": "img/md-187.webp"}, {"id": "md-188", "category": "Vehicle control", "question": "You are entering an interstate. What should you avoid?", "answer": "Crossing the solid lines that separate the ramp from the highway", "choices": ["Crossing the solid lines that separate the ramp from the highway", "Using the acceleration lane", "Signaling your merge", "Matching the speed of traffic"], "explanation": "Use the acceleration lane to match traffic speed, and do not cross the solid lines that divide the entrance from the highway.", "manual_ref": "Sec. 5.J Interstate Driving", "concept_group": "interstate-enter", "img": "img/md-188.webp"}, {"id": "md-189", "category": "Vehicle control", "question": "Your exit on the interstate is coming up. What should you do?", "answer": "Move to the right lane well ahead and slow down in the deceleration lane", "choices": ["Move to the right lane well ahead and slow down in the deceleration lane", "Brake in the travel lane at the exit", "Cut across lanes at the last moment", "Slow down before leaving the highway lanes"], "explanation": "Move to the right lane well before your exit. Start slowing once you are in the deceleration lane, and slow to the posted ramp speed.", "manual_ref": "Sec. 5.J Interstate Driving", "concept_group": "interstate-exit", "img": "img/md-189.webp"}, {"id": "md-190", "category": "Turns", "question": "Where it is legal, how should you make a U-turn?", "answer": "Signal left, stop and yield to oncoming traffic, then turn into the right-hand lane going the other way", "choices": ["Signal left, stop and yield to oncoming traffic, then turn into the right-hand lane going the other way", "Turn from the right lane without signaling", "Make it on a hill so others can see you", "Turn into the nearest left lane going the other way"], "explanation": "Check that U-turns are allowed, signal left, stop and yield to oncoming traffic, and turn into the outside (right-hand) lane traveling in the opposite direction.", "manual_ref": "Sec. 3.H U-turn", "concept_group": "u-turn-how", "img": "img/md-190.webp"}, {"id": "md-191", "category": "Work zones", "question": "You see flashing blue lights on a speed camera unit in a work zone. What do they mean?", "answer": "The work zone speed cameras are active", "choices": ["The work zone speed cameras are active", "The work zone has ended", "Police are directing you to stop", "You may exceed the limit by 10 mph"], "explanation": "Speeding fines may be much higher in work zones. Flashing blue lights mean the speed cameras are active.", "manual_ref": "Sec. 5.H Work Zone Safety", "concept_group": "wz-blue", "img": "img/md-191.webp"}, {"id": "md-192", "category": "Work zones", "question": "Lights are flashing in a work zone. What does that tell you?", "answer": "Workers are present; slow down and watch for them", "choices": ["Workers are present; slow down and watch for them", "The zone is closed for the day", "You may pass on the shoulder", "Only trucks must slow down"], "explanation": "Flashing lights in a work zone mean workers are present. Obey work zone signs, slow down and watch for workers.", "manual_ref": "Sec. 5.H Work Zone Safety", "concept_group": "wz-flashing", "img": "img/md-192.webp"}, {"id": "md-193", "category": "Parking", "question": "You are parking along a street that has a curb. What should you do?", "answer": "Park as close to the curb as possible and set the parking brake", "choices": ["Park as close to the curb as possible and set the parking brake", "Park at least 3 feet from the curb", "Leave the engine running", "Leave the car in drive"], "explanation": "When parking along the road, park as far from traffic as possible, as close to a curb as possible, and always set your parking brake.", "manual_ref": "Sec. 3.J General Parking Rules", "concept_group": "park-curb", "img": "img/md-193.webp"}, {"id": "md-194", "category": "Space", "question": "Following a slow farm vehicle, you are waiting for a safe chance to pass. What can you do to warn drivers behind you?", "answer": "Use your emergency flashers", "choices": ["Use your emergency flashers", "Brake sharply and often", "Flash your high beams at the farm vehicle", "Drive on the shoulder"], "explanation": "If you must follow a slow-moving vehicle while waiting for a safe time to pass, use your emergency flashers to warn others coming up behind you.", "manual_ref": "Sec. 5.L Slow Moving Vehicles", "concept_group": "slow-vehicle-flashers", "img": "img/md-194.webp"}];